   265→
   266→function TemplatePicker({ templates, categories, isLoading, onClose, fetcher }: TemplateSectionProps) {
   267→  const [hoveredCard, setHoveredCard] = useState<string | null>(null);
   268→
   269→  const groupedTemplates = categories.reduce<Record<string, typeof templates>>((acc, cat) => {
