   309→            Close
   310→          </button>
   311→        </div>
   312→
   313→        {/* Start from scratch */}
   314→        <div style={{ marginBottom: "24px" }}>
   315→          <p
   316→            style={{
   317→              fontSize: "13px",
   318→              fontWeight: 600,
   319→              color: "#6d7175",
   320→              textTransform: "uppercase",
   321→              letterSpacing: "0.5px",
   322→              margin: "0 0 10px",
   323→            }}
   324→          >
   325→            Start from scratch
   326→          </p>
   327→          <div
   328→            style={{
   329→              display: "inline-block",
   330→              border: `2px dashed ${hoveredCard === "__blank" ? "#005bd3" : "#c9cccf"}`,
   331→              borderRadius: "10px",
   332→              padding: "16px 24px",
   333→              background: hoveredCard === "__blank" ? "#f3f7ff" : "#f9fafb",
   334→              transition: "all 0.15s ease",
   335→              cursor: "pointer",
   336→              minWidth: "160px",
   337→            }}
   338→            onMouseEnter={() => setHoveredCard("__blank")}
   339→            onMouseLeave={() => setHoveredCard(null)}
   340→          >
   341→            <div style={{ display: "flex", alignItems: "center", gap: "12px" }}>
   342→              <div
   343→                style={{
   344→                  width: "40px",
   345→                  height: "40px",
   346→                  borderRadius: "50%",
   347→                  background: "#e4e5e7",
   348→                  display: "flex",
   349→                  alignItems: "center",
   350→                  justifyContent: "center",
   351→                  fontSize: "18px",
   352→                  flexShrink: 0,
   353→                }}
   354→              >
   355→                📋
   356→              </div>
   357→              <div>
   358→                <p
   359→                  style={{
   360→                    margin: "0 0 2px",
   361→                    fontWeight: 600,
   362→                    fontSize: "14px",
   363→                    color: "#202223",
   364→                  }}
   365→                >
   366→                  Blank chart
   367→                </p>
   368→                <p style={{ margin: 0, fontSize: "12px", color: "#6d7175" }}>
   369→                  Build with your own columns and sizes
   370→                </p>
   371→              </div>
   372→            </div>
   373→            <fetcher.Form method="post" style={{ marginTop: "12px" }}>
   374→              <input type="hidden" name="intent" value="create-blank" />
   375→              <input type="hidden" name="name" value="Untitled Size Chart" />
   376→              <input type="hidden" name="category" value="general" />
   377→              <s-button type="submit" loading={isLoading}>
   378→                Create blank
