   499→
   500→// ---------------------------------------------------------------------------
   501→// Main component
   502→// ---------------------------------------------------------------------------
   503→
   504→export default function SizeCharts() {
   505→  const { charts, plan, templates, categories, canCreate } =
   506→    useLoaderData<typeof loader>();
   507→  const fetcher = useFetcher<typeof action>();
   508→  const shopify = useAppBridge();
   509→
   510→  const [showTemplates, setShowTemplates] = useState(false);
   511→  const [statusFilter, setStatusFilter] = useState<"all" | "active" | "draft">("all");
   512→  const [categoryFilter, setCategoryFilter] = useState("all");
   513→  const [searchQuery, setSearchQuery] = useState("");
   514→
   515→  const isLoading = fetcher.state !== "idle";
   516→
   517→  useEffect(() => {
   518→    if (!fetcher.data) return;
   519→    const data = fetcher.data as ActionData;
   520→    if ("ok" in data && data.ok) {
   521→      shopify.toast.show(data.message);
   522→      if ("redirectId" in data && data.redirectId) {
   523→        window.location.href = `/app/size-charts/${data.redirectId}`;
   524→      } else {
   525→        setShowTemplates(false);
   526→      }
   527→    } else if ("error" in data) {
   528→      shopify.toast.show(data.error, { isError: true });
   529→    }
   530→  }, [fetcher.data, shopify]);
   531→
   532→  const filteredCharts = charts.filter((chart) => {
   533→    const matchesStatus = statusFilter === "all" || chart.status === statusFilter;
   534→    const matchesCategory = categoryFilter === "all" || chart.category === categoryFilter;
   535→    const matchesSearch =
   536→      searchQuery.trim() === "" ||
   537→      chart.name.toLowerCase().includes(searchQuery.toLowerCase());
   538→    return matchesStatus && matchesCategory && matchesSearch;
   539→  });
   540→
   541→  const publishedCount = charts.filter((c) => c.status === "active").length;
   542→  const draftCount = charts.filter((c) => c.status === "draft").length;
   543→  const activeFilteredCount = charts.filter((c) => c.status === "active").length;
   544→  const draftFilteredCount = charts.filter((c) => c.status === "draft").length;
   545→  const maxCharts = plan.limits.maxCharts;
   546→  const isFreePlan = plan.id === "free";
   547→
   548→  const progressPct =
   549→    maxCharts > 0 ? Math.min(100, Math.round((publishedCount / maxCharts) * 100)) : 0;
   550→  const progressColor =
   551→    publishedCount >= maxCharts && maxCharts > 0 ? "#d72c0d" : "#1a73e8";
   552→
   553→  function clearFilters() {
   554→    setStatusFilter("all");
   555→    setCategoryFilter("all");
   556→    setSearchQuery("");
   557→  }
   558→
   559→  return (
   560→    <s-page heading="Size Charts">
   561→      {/* Primary action */}
   562→      <s-button
   563→        slot="primary-action"
   564→        variant="primary"
   565→        onClick={() => setShowTemplates(!showTemplates)}
   566→        disabled={!canCreate || isLoading}
   567→      >
   568→        {canCreate
   569→          ? showTemplates
   570→            ? "Cancel"
   571→            : "Create chart"
   572→          : `Limit reached (${plan.limits.maxCharts})`}
   573→      </s-button>
   574→
   575→      {/* Subtitle */}
   576→      <s-text tone="neutral">
   577→        Manage your size charts and assign them to products
   578→      </s-text>
   579→
   580→      {/* ================================================================ */}
   581→      {/* PLAN LIMIT BANNER                                                 */}
   582→      {/* ================================================================ */}
   583→      {!canCreate && (
   584→        <s-section>
   585→          <div
   586→            style={{
   587→              ...cardStyle,
   588→              background: "#fff8ec",
   589→              border: "1px solid #ffd79d",
   590→              display: "flex",
   591→              alignItems: "center",
   592→              justifyContent: "space-between",
   593→              gap: "16px",
   594→            }}
   595→          >
   596→            <div style={{ display: "flex", alignItems: "flex-start", gap: "12px" }}>
   597→              <span style={{ fontSize: "20px", flexShrink: 0, marginTop: "1px" }}>
   598→                ⚠️
   599→              </span>
   600→              <div>
   601→                <p
   602→                  style={{
   603→                    margin: "0 0 4px",
   604→                    fontSize: "14px",
   605→                    fontWeight: 600,
   606→                    color: "#202223",
   607→                  }}
   608→                >
   609→                  Chart limit reached
   610→                </p>
   611→                <p style={{ margin: 0, fontSize: "13px", color: "#6d7175" }}>
   612→                  You have reached the {plan.limits.maxCharts}-chart limit on the{" "}
   613→                  {plan.name} plan. Upgrade to Starter for unlimited charts with no
   614→                  hidden fees.
   615→                </p>
   616→              </div>
