                            border: `1px solid ${isHovered ? "#005bd3" : "#e3e3e3"}`,
                            borderRadius: "10px",
                            padding: "14px",
                            cursor: "pointer",
                            transition: "all 0.15s ease",
                            display: "flex",
                            flexDirection: "column",
                            alignItems: "center",
                            textAlign: "center",
                          }}
                          onMouseEnter={() => setHoveredCard(cardKey)}
                          onMouseLeave={() => setHoveredCard(null)}
                        >
                          <div
                            style={{
                              width: "40px",
                              height: "40px",
                              borderRadius: "50%",
                              background: "#f0f5ff",
                              display: "flex",
                              alignItems: "center",
                              justifyContent: "center",
                              fontSize: "20px",
                              marginBottom: "8px",
                            }}
                          >
                            {CATEGORY_ICONS[template.category] ?? "📏"}
