  1031→type LoaderData = Awaited<ReturnType<typeof loader>>;
  1032→type ActiveTab = "chart" | "assignments" | "settings";
  1033→
  1034→export default function SizeChartEditor() {
  1035→  const loaderData = useLoaderData<typeof loader>() as LoaderData;
  1036→  const { chart, assignments: initialAssignments, isNew } = loaderData;
  1037→
  1038→  const saveFetcher = useFetcher<typeof action>();
  1039→  const statusFetcher = useFetcher<typeof action>();
  1040→  const assignmentFetcher = useFetcher<typeof action>();
  1041→  const shopify = useAppBridge();
  1042→
  1043→  const [activeTab, setActiveTab] = useState<ActiveTab>("chart");
  1044→  const [name, setName] = useState(chart?.name ?? "Untitled Size Chart");
  1045→  const [category, setCategory] = useState(chart?.category ?? "general");
  1046→  const [status, setStatus] = useState(chart?.status ?? "draft");
  1047→  const [chartData, setChartData] = useState<ChartData>(
  1048→    chart ? parseChartData(chart.data) : makeDefaultData(),
  1049→  );
  1050→  const [assignments, setAssignments] =
  1051→    useState<Assignment[]>(initialAssignments);
  1052→  const [newAssignmentType, setNewAssignmentType] = useState("product");
  1053→  const [newAssignmentValue, setNewAssignmentValue] = useState("");
  1054→
  1055→  const isSaving = saveFetcher.state !== "idle";
  1056→  const isTogglingStatus = statusFetcher.state !== "idle";
  1057→
  1058→  // Check for ?saved=1 on mount (after redirect from new chart creation)
  1059→  useEffect(() => {
  1060→    if (typeof window !== "undefined") {
  1061→      const url = new URL(window.location.href);
  1062→      if (url.searchParams.get("saved") === "1") {
  1063→        shopify.toast.show("Chart created successfully");
  1064→        url.searchParams.delete("saved");
  1065→        window.history.replaceState({}, "", url.toString());
  1066→      }
  1067→    }
  1068→  }, [shopify]);
  1069→
  1070→  // Save feedback
  1071→  useEffect(() => {
  1072→    if (!saveFetcher.data) return;
  1073→    const data = saveFetcher.data;
  1074→    if ("ok" in data && data.ok) {
  1075→      shopify.toast.show(data.message ?? "Saved");
  1076→    } else if ("error" in data) {
  1077→      shopify.toast.show(data.error ?? "An error occurred", { isError: true });
  1078→    }
  1079→  }, [saveFetcher.data, shopify]);
  1080→
  1081→  // Status toggle feedback
  1082→  useEffect(() => {
  1083→    if (!statusFetcher.data) return;
  1084→    const data = statusFetcher.data;
  1085→    if ("ok" in data && data.ok) {
  1086→      shopify.toast.show(data.message ?? "Status updated");
  1087→      if ("newStatus" in data && typeof data.newStatus === "string") {
  1088→        setStatus(data.newStatus);
  1089→      }
  1090→    } else if ("error" in data) {
  1091→      shopify.toast.show(data.error ?? "An error occurred", { isError: true });
  1092→    }
  1093→  }, [statusFetcher.data, shopify]);
  1094→
  1095→  // Assignment feedback
  1096→  useEffect(() => {
  1097→    if (!assignmentFetcher.data) return;
  1098→    const data = assignmentFetcher.data;
  1099→    if ("ok" in data && data.ok) {
  1100→      shopify.toast.show(data.message ?? "Done");
  1101→      setNewAssignmentValue("");
  1102→    } else if ("error" in data) {
  1103→      shopify.toast.show(data.error ?? "An error occurred", { isError: true });
  1104→    }
  1105→  }, [assignmentFetcher.data, shopify]);
  1106→
  1107→  const handleSave = () => {
  1108→    const formData = new FormData();
  1109→    formData.set("intent", "save");
  1110→    formData.set("name", name);
  1111→    formData.set("category", category);
  1112→    formData.set("status", status);
  1113→    formData.set("data", JSON.stringify(chartData));
  1114→    saveFetcher.submit(formData, { method: "post" });
  1115→  };
  1116→
  1117→  const handleToggleStatus = () => {
  1118→    const formData = new FormData();
  1119→    formData.set("intent", "toggle-status");
  1120→    statusFetcher.submit(formData, { method: "post" });
  1121→  };
  1122→
  1123→  const handleAddAssignment = () => {
  1124→    if (!newAssignmentValue.trim() && newAssignmentType !== "all") return;
  1125→    const formData = new FormData();
  1126→    formData.set("intent", "add-assignment");
  1127→    formData.set("assignmentType", newAssignmentType);
  1128→    formData.set(
  1129→      "assignmentValue",
  1130→      newAssignmentType === "all" ? "*" : newAssignmentValue.trim(),
  1131→    );
  1132→    assignmentFetcher.submit(formData, { method: "post" });
  1133→    setAssignments((prev) => [
  1134→      ...prev,
  1135→      {
  1136→        id: `temp-${Date.now()}`,
  1137→        assignmentType: newAssignmentType,
  1138→        assignmentValue:
  1139→          newAssignmentType === "all" ? "*" : newAssignmentValue.trim(),
  1140→      },
  1141→    ]);
  1142→  };
  1143→
  1144→  const handleRemoveAssignment = (assignmentId: string) => {
  1145→    const formData = new FormData();
  1146→    formData.set("intent", "remove-assignment");
  1147→    formData.set("assignmentId", assignmentId);
  1148→    assignmentFetcher.submit(formData, { method: "post" });
  1149→    setAssignments((prev) => prev.filter((a) => a.id !== assignmentId));
  1150→  };
  1151→
  1152→  const assignmentTypeLabel = (type: string) =>
  1153→    ASSIGNMENT_TYPES.find((t) => t.value === type)?.label ?? type;
  1154→
  1155→  return (
  1156→    <s-page
  1157→      heading={isNew ? "New Size Chart" : name}
  1158→      back-action-url="/app/size-charts"
  1159→    >
  1160→      <s-button
  1161→        slot="primary-action"
  1162→        variant="primary"
  1163→        onClick={handleSave}
  1164→        loading={isSaving}
  1165→        disabled={isSaving}
  1166→      >
  1167→        {isSaving ? "Saving..." : "Save"}
  1168→      </s-button>
  1169→
  1170→      <s-button
  1171→        slot="secondary-action"
  1172→        onClick={handleToggleStatus}
  1173→        loading={isTogglingStatus}
  1174→        disabled={isNew || isTogglingStatus}
  1175→      >
  1176→        {status === "active" ? "Unpublish" : "Publish"}
  1177→      </s-button>
  1178→
  1179→      {/* ================================================================ */}
  1180→      {/* Tab navigation                                                     */}
  1181→      {/* ================================================================ */}
  1182→      <s-section>
  1183→        <div
  1184→          style={{
  1185→            display: "flex",
  1186→            gap: "0",
  1187→            borderBottom: "1px solid #e1e3e5",
  1188→            marginBottom: "4px",
  1189→          }}
  1190→        >
  1191→          {(
  1192→            [
  1193→              { id: "chart" as const, label: "Size Chart" },
  1194→              { id: "assignments" as const, label: "Assignments" },
  1195→              { id: "settings" as const, label: "Settings" },
  1196→            ] satisfies { id: ActiveTab; label: string }[]
