interface ChartPreviewProps {
  data: ChartData;
  name: string;
  status: string;
}

function ChartPreview({ data, name, status }: ChartPreviewProps) {
  return (
    <div
      style={{
        border: "1px solid #e3e3e3",
        borderRadius: "12px",
        overflow: "hidden",
        background: "#fff",
        boxShadow: "0 2px 8px rgba(0,0,0,0.08)",
        fontSize: "13px",
      }}
    >
      {/* Widget header bar */}
      <div
        style={{
          background: "#1a1a1a",
          padding: "12px 16px",
