            style={{
              fontSize: "16px",
              color: "#6d7175",
              lineHeight: 1,
              cursor: "default",
            }}
          >
            &times;
          </span>
        </div>
      </div>

      {/* Unit tab strip */}
      <div
        style={{
          background: "#f6f6f7",
          borderBottom: "1px solid #e1e3e5",
          padding: "6px 16px",
          display: "flex",
          gap: "4px",
        }}
      >
        {data.units.available.map((unit) => (
          <span
            key={unit}
            style={{
              padding: "2px 10px",
              borderRadius: "12px",
              fontSize: "11px",
              fontWeight: 600,
              background:
                unit === data.units.default ? "#202223" : "transparent",
              color: unit === data.units.default ? "#ffffff" : "#8c9196",
              cursor: "default",
            }}
          >
            {unit}
          </span>
        ))}
      </div>

      {/* Preview table */}
      <div style={{ overflowX: "auto" }}>
