// ---------------------------------------------------------------------------
// Table Editor Component
// ---------------------------------------------------------------------------

interface TableEditorProps {
  data: ChartData;
  onChange: (data: ChartData) => void;
}

function TableEditor({ data, onChange }: TableEditorProps) {
  const headerInputRefs = useRef<(HTMLInputElement | null)[]>([]);

  const updateCell = (rowIndex: number, header: string, value: string) => {
    const newRows = data.rows.map((row, i) => {
      if (i !== rowIndex) return row;
      return { ...row, [header]: value };
    });
    onChange({ ...data, rows: newRows });
  };

  const updateHeader = (headerIndex: number, value: string) => {
    const oldHeader = data.headers[headerIndex];
    const newHeaders = data.headers.map((h, i) =>
      i === headerIndex ? value : h,
    );
    const newRows = data.rows.map((row) => {
      const newRow: Record<string, string> = {};
      data.headers.forEach((h, i) => {
        const key = i === headerIndex ? value : h;
        newRow[key] = row[h] ?? "";
      });
      return newRow;
    });
    onChange({ ...data, headers: newHeaders, rows: newRows });
    void oldHeader;
  };

  const addRow = () => {
    const emptyRow: Record<string, string> = {};
    data.headers.forEach((h) => {
      emptyRow[h] = "";
    });
    onChange({ ...data, rows: [...data.rows, emptyRow] });
  };

  const removeRow = (rowIndex: number) => {
    onChange({ ...data, rows: data.rows.filter((_, i) => i !== rowIndex) });
  };

  const addColumn = () => {
    const newHeader = `Column ${data.headers.length + 1}`;
    const newHeaders = [...data.headers, newHeader];
    const newRows = data.rows.map((row) => ({ ...row, [newHeader]: "" }));
    onChange({ ...data, headers: newHeaders, rows: newRows });
  };

  const removeColumn = (headerIndex: number) => {
    if (data.headers.length <= 1) return;
    const removedHeader = data.headers[headerIndex];
    const newHeaders = data.headers.filter((_, i) => i !== headerIndex);
    const newRows = data.rows.map((row) => {
      const newRow: Record<string, string> = {};
      newHeaders.forEach((h) => {
        newRow[h] = row[h] ?? "";
      });
      return newRow;
    });
    onChange({ ...data, headers: newHeaders, rows: newRows });
    void removedHeader;
  };

  const toggleUnit = (unit: string) => {
    onChange({ ...data, units: { ...data.units, default: unit } });
  };

  return (
    <div>
      {/* Toolbar — unit toggle + row/col count */}
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: "8px",
          marginBottom: "10px",
        }}
      >
        <span
          style={{
            fontSize: "12px",
            fontWeight: 600,
            color: "#6d7175",
            textTransform: "uppercase",
            letterSpacing: "0.04em",
          }}
        >
          Units
        </span>
        <div
          style={{
            display: "flex",
            gap: "4px",
            background: "#f6f6f7",
            borderRadius: "20px",
            padding: "3px",
            border: "1px solid #e1e3e5",
          }}
        >
          {data.units.available.map((unit) => (
            <button
              key={unit}
              type="button"
              onClick={() => toggleUnit(unit)}
              style={{
                padding: "3px 14px",
                borderRadius: "16px",
                border: "none",
                background:
                  data.units.default === unit ? "#2c6ecb" : "transparent",
                color: data.units.default === unit ? "#ffffff" : "#6d7175",
                fontWeight: data.units.default === unit ? 700 : 500,
                cursor: "pointer",
                fontSize: "12px",
                lineHeight: "20px",
                transition: "all 0.12s ease",
                fontFamily: "inherit",
              }}
            >
              {unit}
            </button>
          ))}
        </div>
        <div
          style={{
            marginLeft: "auto",
            fontSize: "12px",
            color: "#8c9196",
            fontWeight: 500,
            background: "#f6f6f7",
            border: "1px solid #e1e3e5",
            borderRadius: "6px",
            padding: "3px 10px",
          }}
        >
          {data.rows.length} rows &middot; {data.headers.length} cols
        </div>
      </div>

      {/* Table */}
      <div
        style={{
          border: "1px solid #e1e3e5",
          borderRadius: "8px",
          overflow: "hidden",
          overflowX: "auto",
        }}
      >
        <table
          style={{
            width: "100%",
            borderCollapse: "collapse",
            fontSize: "13px",
            tableLayout: "auto",
          }}
        >
          <thead>
            <tr>
              {data.headers.map((header, hi) => (
                <th
                  key={hi}
                  style={{
                    background: "#f6f6f7",
                    borderBottom: "2px solid #e1e3e5",
                    borderRight:
                      hi < data.headers.length - 1
                        ? "1px solid #e1e3e5"
                        : "none",
                    padding: "0",
                    position: "relative",
                    minWidth: "110px",
                  }}
                >
                  <div
                    style={{
                      display: "flex",
                      alignItems: "center",
                      padding: "2px 6px 2px 10px",
                    }}
                  >
                    <input
                      ref={(el) => {
                        headerInputRefs.current[hi] = el;
                      }}
                      value={header}
                      onChange={(e) =>
                        updateHeader(hi, (e.target as HTMLInputElement).value)
                      }
                      style={{
                        flex: 1,
                        border: "none",
                        background: "transparent",
                        fontWeight: 700,
                        fontSize: "12px",
                        color: "#202223",
                        padding: "8px 4px",
                        outline: "none",
                        minWidth: "60px",
                        textTransform: "uppercase",
                        letterSpacing: "0.04em",
                        fontFamily: "inherit",
                      }}
                      placeholder={`Col ${hi + 1}`}
                    />
                    {data.headers.length > 1 && (
                      <button
                        type="button"
                        onClick={() => removeColumn(hi)}
                        title="Remove column"
                        style={{
                          background: "none",
                          border: "none",
                          cursor: "pointer",
                          color: "#c9cccf",
                          padding: "2px 4px",
                          borderRadius: "4px",
                          fontSize: "15px",
                          lineHeight: 1,
                          flexShrink: 0,
                          transition: "color 0.1s, background 0.1s",
                          fontFamily: "inherit",
                        }}
                        onMouseEnter={(e) => {
                          (e.currentTarget as HTMLButtonElement).style.color =
                            "#d82c0d";
                          (
                            e.currentTarget as HTMLButtonElement
                          ).style.background = "#fee2e2";
                        }}
                        onMouseLeave={(e) => {
                          (e.currentTarget as HTMLButtonElement).style.color =
                            "#c9cccf";
                          (
                            e.currentTarget as HTMLButtonElement
                          ).style.background = "none";
                        }}
                      >
                        &times;
                      </button>
                    )}
                  </div>
                </th>
              ))}

              {/* Add column header cell */}
              <th
                style={{
                  background: "#f6f6f7",
                  borderBottom: "2px solid #e1e3e5",
                  padding: "0",
                  width: "40px",
                  minWidth: "40px",
                }}
              >
                <button
                  type="button"
                  onClick={addColumn}
                  title="Add column"
                  style={{
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    width: "100%",
                    height: "100%",
                    minHeight: "38px",
                    background: "none",
                    border: "none",
                    cursor: "pointer",
                    color: "#2c6ecb",
                    fontSize: "20px",
                    lineHeight: 1,
                    padding: "0",
                    transition: "background 0.1s",
                    fontFamily: "inherit",
                  }}
                  onMouseEnter={(e) => {
                    (e.currentTarget as HTMLButtonElement).style.background =
                      "#e8f0fe";
                  }}
                  onMouseLeave={(e) => {
                    (e.currentTarget as HTMLButtonElement).style.background =
                      "none";
                  }}
                >
                  +
                </button>
              </th>

              {/* Row actions header spacer */}
              <th
                style={{
                  background: "#f6f6f7",
                  borderBottom: "2px solid #e1e3e5",
                  width: "36px",
                  minWidth: "36px",
                }}
              />
            </tr>
          </thead>
          <tbody>
            {data.rows.map((row, ri) => (
              <tr
                key={ri}
                style={{
                  background: ri % 2 === 0 ? "#ffffff" : "#fafbfb",
                  transition: "background 0.1s",
                }}
                onMouseEnter={(e) => {
                  (e.currentTarget as HTMLTableRowElement).style.background =
                    "#f0f5ff";
                }}
                onMouseLeave={(e) => {
                  (e.currentTarget as HTMLTableRowElement).style.background =
                    ri % 2 === 0 ? "#ffffff" : "#fafbfb";
                }}
              >
                {data.headers.map((header, hi) => (
                  <td
                    key={hi}
                    style={{
                      borderBottom:
                        ri < data.rows.length - 1
                          ? "1px solid #e1e3e5"
                          : "none",
                      borderRight:
                        hi < data.headers.length - 1
                          ? "1px solid #e1e3e5"
                          : "none",
                      padding: "0",
                    }}
                  >
                    <input
                      value={row[header] ?? ""}
                      onChange={(e) =>
                        updateCell(
                          ri,
                          header,
                          (e.target as HTMLInputElement).value,
                        )
                      }
                      style={{
                        width: "100%",
                        border: "none",
                        background: "transparent",
                        padding: "9px 10px",
                        fontSize: "13px",
                        color: "#202223",
                        outline: "none",
                        boxSizing: "border-box",
                        fontFamily: "inherit",
                      }}
                      onFocus={(e) => {
                        (
                          e.target as HTMLInputElement
                        ).parentElement!.style.boxShadow =
                          "inset 0 0 0 2px #2c6ecb";
                        (
                          e.target as HTMLInputElement
                        ).parentElement!.style.background = "#f0f5ff";
                      }}
                      onBlur={(e) => {
                        (
                          e.target as HTMLInputElement
                        ).parentElement!.style.boxShadow = "none";
                        (
                          e.target as HTMLInputElement
                        ).parentElement!.style.background = "transparent";
                      }}
                      placeholder="—"
                    />
                  </td>
                ))}

                {/* Column spacer — aligns under add column button */}
                <td
                  style={{
                    borderBottom:
                      ri < data.rows.length - 1 ? "1px solid #e1e3e5" : "none",
                    borderRight: "1px solid #e1e3e5",
                    width: "40px",
                    background: "transparent",
                  }}
                />

                {/* Remove row button */}
                <td
                  style={{
                    borderBottom:
                      ri < data.rows.length - 1 ? "1px solid #e1e3e5" : "none",
                    padding: "0",
                    textAlign: "center",
                    width: "36px",
                    background: "transparent",
                  }}
                >
                  <button
                    type="button"
                    onClick={() => removeRow(ri)}
                    title="Remove row"
                    style={{
                      background: "none",
                      border: "none",
                      cursor: "pointer",
                      color: "#c9cccf",
                      fontSize: "16px",
                      lineHeight: 1,
                      padding: "4px 8px",
                      borderRadius: "4px",
                      transition: "color 0.1s, background 0.1s",
                      fontFamily: "inherit",
                    }}
                    onMouseEnter={(e) => {
                      (e.currentTarget as HTMLButtonElement).style.color =
                        "#d82c0d";
                      (e.currentTarget as HTMLButtonElement).style.background =
                        "#fee2e2";
                    }}
                    onMouseLeave={(e) => {
                      (e.currentTarget as HTMLButtonElement).style.color =
                        "#c9cccf";
                      (e.currentTarget as HTMLButtonElement).style.background =
                        "none";
                    }}
                  >
                    &times;
                  </button>
                </td>
              </tr>
            ))}

            {/* Add row footer */}
            <tr>
              <td
                colSpan={data.headers.length + 2}
                style={{
                  padding: "0",
                  background: "#f6f6f7",
                  borderTop: "1px solid #e1e3e5",
                }}
              >
                <button
                  type="button"
                  onClick={addRow}
                  style={{
                    display: "block",
                    width: "100%",
                    background: "none",
                    border: "none",
                    cursor: "pointer",
                    color: "#2c6ecb",
                    fontSize: "13px",
                    fontWeight: 600,
                    padding: "10px 14px",
                    textAlign: "left",
                    transition: "background 0.1s",
                    fontFamily: "inherit",
                  }}
                  onMouseEnter={(e) => {
                    (e.currentTarget as HTMLButtonElement).style.background =
                      "#e8f0fe";
                  }}
                  onMouseLeave={(e) => {
                    (e.currentTarget as HTMLButtonElement).style.background =
                      "none";
                  }}
                >
                  + Add row
                </button>
              </td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Chart Preview Component — Realistic storefront widget mockup
// ---------------------------------------------------------------------------

interface ChartPreviewProps {
  data: ChartData;
  name: string;
  status: string;
}

function ChartPreview({ data, name, status }: ChartPreviewProps) {
  return (
    <div
      style={{
        border: "1px solid #e3e3e3",
        borderRadius: "12px",
        overflow: "hidden",
        background: "#fff",
        boxShadow: "0 2px 8px rgba(0,0,0,0.08)",
        fontSize: "13px",
      }}
    >
      {/* Widget header bar */}
      <div
        style={{
          background: "#1a1a1a",
          padding: "12px 16px",
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
        }}
      >
        <span
          style={{
            fontWeight: 700,
            fontSize: "13px",
            color: "#ffffff",
            letterSpacing: "0.01em",
          }}
        >
          {name || "Size Guide"}
        </span>
        <div style={{ display: "flex", gap: "8px", alignItems: "center" }}>
          <div style={{ display: "flex", gap: "4px", alignItems: "center" }}>
            <div
              style={{
                width: "6px",
                height: "6px",
                borderRadius: "50%",
                background: status === "active" ? "#24c57b" : "#8c9196",
              }}
            />
            <span
              style={{
                fontSize: "10px",
                color: status === "active" ? "#24c57b" : "#8c9196",
                fontWeight: 600,
              }}
            >
              {status === "active" ? "Live" : "Draft"}
            </span>
          </div>
          <span
            style={{
              fontSize: "16px",
              color: "#6d7175",
              lineHeight: 1,
              cursor: "default",
            }}
          >
            &times;
          </span>
        </div>
      </div>

      {/* Unit tab strip */}
      <div
        style={{
          background: "#f6f6f7",
          borderBottom: "1px solid #e1e3e5",
          padding: "6px 16px",
          display: "flex",
          gap: "4px",
        }}
      >
        {data.units.available.map((unit) => (
          <span
            key={unit}
            style={{
              padding: "2px 10px",
              borderRadius: "12px",
              fontSize: "11px",
              fontWeight: 600,
              background:
                unit === data.units.default ? "#202223" : "transparent",
              color: unit === data.units.default ? "#ffffff" : "#8c9196",
              cursor: "default",
            }}
          >
            {unit}
          </span>
        ))}
      </div>

      {/* Preview table */}
      <div style={{ overflowX: "auto" }}>
        <table
          style={{
            width: "100%",
            borderCollapse: "collapse",
            fontSize: "12px",
          }}
        >
          <thead>
            <tr>
              {data.headers.map((h, i) => (
                <th
                  key={i}
                  style={{
                    background: "#f6f6f7",
                    padding: "8px 12px",
                    textAlign: "left",
                    fontWeight: 700,
                    fontSize: "11px",
                    textTransform: "uppercase",
                    letterSpacing: "0.05em",
                    color: "#6d7175",
                    borderBottom: "1px solid #e1e3e5",
                    borderRight:
                      i < data.headers.length - 1
                        ? "1px solid #e1e3e5"
                        : "none",
                    whiteSpace: "nowrap",
                  }}
                >
                  {h}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {data.rows.map((row, ri) => (
              <tr
                key={ri}
                style={{ background: ri % 2 === 0 ? "#fff" : "#fafbfb" }}
              >
                {data.headers.map((h, hi) => (
                  <td
                    key={hi}
                    style={{
                      padding: "8px 12px",
                      borderBottom:
                        ri < data.rows.length - 1
                          ? "1px solid #e1e3e5"
                          : "none",
                      borderRight:
                        hi < data.headers.length - 1
                          ? "1px solid #e1e3e5"
                          : "none",
                      color: row[h] ? "#202223" : "#c9cccf",
                      fontWeight: hi === 0 ? 600 : 400,
                    }}
                  >
                    {row[h] || "—"}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Footer */}
      <div
        style={{
          padding: "8px 16px",
          background: "#f6f6f7",
          borderTop: "1px solid #e1e3e5",
          display: "flex",
          alignItems: "center",
          justifyContent: "space-between",
        }}
      >
        <span style={{ fontSize: "11px", color: "#8c9196" }}>
          Measurements in {data.units.default}
        </span>
        <span style={{ fontSize: "11px", color: "#8c9196", fontWeight: 600 }}>
          {data.rows.length} sizes available
        </span>
      </div>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Main Component
// ---------------------------------------------------------------------------

type LoaderData = Awaited<ReturnType<typeof loader>>;
type ActiveTab = "chart" | "assignments" | "position" | "recommendation" | "settings";

export default function SizeChartEditor() {
  const loaderData = useLoaderData<typeof loader>() as LoaderData;
  const { chart, assignments: initialAssignments, isNew } = loaderData;

  const saveFetcher = useFetcher<typeof action>();
  const statusFetcher = useFetcher<typeof action>();
  const assignmentFetcher = useFetcher<typeof action>();
  const shopify = useAppBridge();

  const [activeTab, setActiveTab] = useState<ActiveTab>("chart");
  const [name, setName] = useState(chart?.name ?? "Untitled Size Chart");
  const [category, setCategory] = useState(chart?.category ?? "general");
  const [status, setStatus] = useState(chart?.status ?? "draft");
  const [chartData, setChartData] = useState<ChartData>(
    chart ? parseChartData(chart.data) : makeDefaultData(),
  );
  const [assignments, setAssignments] =
    useState<Assignment[]>(initialAssignments);
  const [newAssignmentType, setNewAssignmentType] = useState("product");
  const [newAssignmentValue, setNewAssignmentValue] = useState("");

  const isSaving = saveFetcher.state !== "idle";
  const isTogglingStatus = statusFetcher.state !== "idle";

  // Check for ?saved=1 on mount (after redirect from new chart creation)
  useEffect(() => {
    if (typeof window !== "undefined") {
      const url = new URL(window.location.href);
      if (url.searchParams.get("saved") === "1") {
        shopify.toast.show("Chart created successfully");
        url.searchParams.delete("saved");
        window.history.replaceState({}, "", url.toString());
      }
    }
  }, [shopify]);

  // Save feedback
  useEffect(() => {
    if (!saveFetcher.data) return;
    const data = saveFetcher.data;
    if ("ok" in data && data.ok) {
      shopify.toast.show(data.message ?? "Saved");
    } else if ("error" in data) {
      shopify.toast.show(data.error ?? "An error occurred", { isError: true });
    }
  }, [saveFetcher.data, shopify]);

  // Status toggle feedback
  useEffect(() => {
    if (!statusFetcher.data) return;
    const data = statusFetcher.data;
    if ("ok" in data && data.ok) {
      shopify.toast.show(data.message ?? "Status updated");
      if ("newStatus" in data && typeof data.newStatus === "string") {
        setStatus(data.newStatus);
      }
    } else if ("error" in data) {
      shopify.toast.show(data.error ?? "An error occurred", { isError: true });
    }
  }, [statusFetcher.data, shopify]);

  // Assignment feedback
  useEffect(() => {
    if (!assignmentFetcher.data) return;
    const data = assignmentFetcher.data;
    if ("ok" in data && data.ok) {
      shopify.toast.show(data.message ?? "Done");
      setNewAssignmentValue("");
    } else if ("error" in data) {
      shopify.toast.show(data.error ?? "An error occurred", { isError: true });
    }
  }, [assignmentFetcher.data, shopify]);

  const handleSave = () => {
    const formData = new FormData();
    formData.set("intent", "save");
    formData.set("name", name);
    formData.set("category", category);
    formData.set("status", status);
    formData.set("data", JSON.stringify(chartData));
    saveFetcher.submit(formData, { method: "post" });
  };

  const handleToggleStatus = () => {
    const formData = new FormData();
    formData.set("intent", "toggle-status");
    statusFetcher.submit(formData, { method: "post" });
  };

  const handleAddAssignment = () => {
    if (!newAssignmentValue.trim() && newAssignmentType !== "all") return;
    const formData = new FormData();
    formData.set("intent", "add-assignment");
    formData.set("assignmentType", newAssignmentType);
    formData.set(
      "assignmentValue",
      newAssignmentType === "all" ? "*" : newAssignmentValue.trim(),
    );
    assignmentFetcher.submit(formData, { method: "post" });
    setAssignments((prev) => [
      ...prev,
      {
        id: `temp-${Date.now()}`,
        assignmentType: newAssignmentType,
        assignmentValue:
          newAssignmentType === "all" ? "*" : newAssignmentValue.trim(),
      },
    ]);
  };

  const handleRemoveAssignment = (assignmentId: string) => {
    const formData = new FormData();
    formData.set("intent", "remove-assignment");
    formData.set("assignmentId", assignmentId);
    assignmentFetcher.submit(formData, { method: "post" });
    setAssignments((prev) => prev.filter((a) => a.id !== assignmentId));
  };

  const assignmentTypeLabel = (type: string) =>
    ASSIGNMENT_TYPES.find((t) => t.value === type)?.label ?? type;

  return (
    <s-page
      heading={isNew ? "New Size Chart" : name}
      back-action-url="/app/size-charts"
    >
      <s-button
        slot="primary-action"
        variant="primary"
        onClick={handleSave}
        loading={isSaving}
        disabled={isSaving}
      >
        {isSaving ? "Saving..." : "Save"}
      </s-button>

      <s-button
        slot="secondary-action"
        onClick={handleToggleStatus}
        loading={isTogglingStatus}
        disabled={isNew || isTogglingStatus}
      >
        {status === "active" ? "Unpublish" : "Publish"}
      </s-button>

      {/* ================================================================ */}
      {/* Tab navigation                                                     */}
      {/* ================================================================ */}
      <s-section>
        <div
          style={{
            display: "flex",
            gap: "0",
            borderBottom: "1px solid #e1e3e5",
            marginBottom: "4px",
          }}
        >
          {(
            [
              { id: "chart" as const, label: "Size Chart" },
              { id: "assignments" as const, label: "Assignments" },
              { id: "settings" as const, label: "Settings" },
            ] satisfies { id: ActiveTab; label: string }[]
          ).map((tab) => (
            <button
              key={tab.id}
              type="button"
              onClick={() => setActiveTab(tab.id)}
              style={tabStyle(activeTab === tab.id)}
            >
              {tab.label}
              {tab.id === "assignments" && assignments.length > 0 && (
                <span
                  style={{
                    marginLeft: "6px",
                    background:
                      activeTab === "assignments" ? "#202223" : "#e4e5e7",
                    color:
                      activeTab === "assignments" ? "#ffffff" : "#6d7175",
                    borderRadius: "10px",
                    fontSize: "11px",
                    fontWeight: 700,
                    padding: "1px 6px",
                    lineHeight: "16px",
                    display: "inline-block",
                    verticalAlign: "middle",
                  }}
                >
                  {assignments.length}
                </span>
              )}
            </button>
          ))}
        </div>

        {/* ============================================================== */}
        {/* TAB: Size Chart                                                 */}
        {/* ============================================================== */}
        <div style={{ display: activeTab === "chart" ? "block" : "none" }}>
          {/* General Settings card */}
          <div style={{ ...cardStyle, marginBottom: "16px" }}>
            <div
              style={{
                display: "flex",
                alignItems: "center",
                justifyContent: "space-between",
                marginBottom: "16px",
              }}
            >
              <p style={sectionTitle}>General Settings</p>
              <span
                style={badgeStyle(status === "active" ? "success" : "neutral")}
              >
                {status === "active" ? "Published" : "Draft"}
              </span>
            </div>

            {/* Name field */}
            <div style={{ marginBottom: "16px" }}>
              <label style={labelStyle} htmlFor="chart-name">
                Chart name
              </label>
              <input
                id="chart-name"
                value={name}
                onChange={(e) => setName((e.target as HTMLInputElement).value)}
                placeholder="e.g. Women's Tops Size Chart"
                style={inputStyle}
                onFocus={(e) => focusInput(e.target as HTMLInputElement)}
                onBlur={(e) => blurInput(e.target as HTMLInputElement)}
              />
            </div>

            {/* Category + Status row */}
            <div
              style={{ display: "flex", gap: "16px", alignItems: "flex-end" }}
            >
              <div style={{ flex: 1 }}>
                <label style={labelStyle} htmlFor="chart-category">
                  Category
                </label>
                <select
                  id="chart-category"
                  value={category}
                  onChange={(e) =>
                    setCategory((e.target as HTMLSelectElement).value)
                  }
                  style={{
                    ...inputStyle,
                    cursor: "pointer",
                    appearance: "auto",
                  }}
                  onFocus={(e) => focusInput(e.target as HTMLSelectElement)}
                  onBlur={(e) => blurInput(e.target as HTMLSelectElement)}
                >
                  {CATEGORIES.map((c) => (
                    <option key={c.value} value={c.value}>
                      {c.label}
                    </option>
                  ))}
                </select>
              </div>

              <div>
                <label style={{ ...labelStyle, color: "#6d7175" }}>
                  Status
                </label>
                <div style={{ paddingBottom: "9px" }}>
                  <span
                    style={{
                      ...badgeStyle(
                        status === "active" ? "success" : "neutral",
                      ),
                      fontSize: "12px",
                      padding: "4px 10px",
                    }}
                  >
                    {status === "active" ? "Published" : "Draft"}
                  </span>
                </div>
              </div>
            </div>
          </div>

          {/* Size Table card */}
          <div style={cardStyle}>
            <div style={{ marginBottom: "14px" }}>
              <p style={sectionTitle}>Size Table</p>
              <p
                style={{
                  fontSize: "13px",
                  color: "#6d7175",
                  margin: "4px 0 0",
                }}
              >
                Click any cell to edit. Click a column header to rename it. Use
                the + buttons to add rows or columns.
              </p>
            </div>
            <TableEditor data={chartData} onChange={setChartData} />
          </div>
        </div>

        {/* ============================================================== */}
        {/* TAB: Assignments                                                */}
        {/* ============================================================== */}
        <div
          style={{ display: activeTab === "assignments" ? "block" : "none" }}
        >
          {/* Current Assignments card */}
          <div style={{ ...cardStyle, marginBottom: "16px" }}>
            <div style={{ marginBottom: "16px" }}>
              <p style={sectionTitle}>Current Assignments</p>
              <p
                style={{
                  fontSize: "13px",
                  color: "#6d7175",
                  margin: "4px 0 0",
                }}
              >
                This chart will appear on matching product pages.
              </p>
            </div>

            {/* New chart info banner */}
            {isNew && (
              <div
                style={{
                  background: "#e8f0fe",
                  border: "1px solid #c5d8f6",
                  borderRadius: "8px",
                  padding: "12px 14px",
                  display: "flex",
                  alignItems: "flex-start",
                  gap: "10px",
                }}
              >
                <span
                  style={{
                    fontSize: "16px",
                    lineHeight: 1,
                    marginTop: "1px",
                  }}
                >
                  &#9432;
                </span>
                <p
                  style={{
                    margin: 0,
                    fontSize: "13px",
                    color: "#3b3f8c",
                    fontWeight: 500,
                  }}
                >
                  Save the chart first to add product assignments.
                </p>
              </div>
            )}

            {/* Existing assignments list */}
            {assignments.length > 0 && (
              <div
                style={{
                  border: "1px solid #e3e3e3",
                  borderRadius: "8px",
                  overflow: "hidden",
                }}
              >
                {assignments.map((assignment, i) => (
                  <div
                    key={assignment.id}
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: "12px",
                      padding: "11px 14px",
                      background: i % 2 === 0 ? "#ffffff" : "#fafbfb",
                      borderBottom:
                        i < assignments.length - 1
                          ? "1px solid #e3e3e3"
                          : "none",
                    }}
                  >
                    <span style={badgeStyle("info")}>
                      {assignmentTypeLabel(assignment.assignmentType)}
                    </span>
                    <span
                      style={{
                        flex: 1,
                        fontSize: "13px",
                        color: "#202223",
                        fontWeight: 500,
                        fontFamily: "monospace",
                      }}
                    >
                      {assignment.assignmentValue === "*"
                        ? "All products"
                        : assignment.assignmentValue}
                    </span>
                    <button
                      type="button"
                      onClick={() => handleRemoveAssignment(assignment.id)}
                      style={{
                        background: "none",
                        border: "none",
                        cursor: "pointer",
                        color: "#8c9196",
                        fontSize: "12px",
                        fontWeight: 600,
                        padding: "4px 8px",
                        borderRadius: "4px",
                        transition: "color 0.1s, background 0.1s",
                        fontFamily: "inherit",
                      }}
                      onMouseEnter={(e) => {
                        (e.currentTarget as HTMLButtonElement).style.color =
                          "#d82c0d";
                        (
                          e.currentTarget as HTMLButtonElement
                        ).style.background = "#fee2e2";
                      }}
                      onMouseLeave={(e) => {
                        (e.currentTarget as HTMLButtonElement).style.color =
                          "#8c9196";
                        (
                          e.currentTarget as HTMLButtonElement
                        ).style.background = "none";
                      }}
                    >
                      Remove
                    </button>
                  </div>
                ))}
              </div>
            )}

            {/* Empty state */}
            {assignments.length === 0 && !isNew && (
              <div
                style={{
                  border: "1.5px dashed #c9cccf",
                  borderRadius: "8px",
                  padding: "28px 16px",
                  textAlign: "center",
                  background: "#fafbfb",
                }}
              >
                <div
                  style={{
                    fontSize: "28px",
                    marginBottom: "8px",
                    lineHeight: 1,
                  }}
                >
                  &#128205;
                </div>
                <p
                  style={{
                    margin: 0,
                    fontSize: "14px",
                    color: "#202223",
                    fontWeight: 600,
                  }}
                >
                  No assignments yet
                </p>
                <p
                  style={{
                    margin: "4px 0 0",
                    fontSize: "13px",
                    color: "#8c9196",
                  }}
                >
                  Add an assignment below to show this chart on product pages.
                </p>
              </div>
            )}
          </div>

          {/* Add Assignment card */}
          {!isNew && (
            <div style={cardStyle}>
              <div style={{ marginBottom: "14px" }}>
                <p style={sectionTitle}>Add Assignment</p>
                <p
                  style={{
                    fontSize: "13px",
                    color: "#6d7175",
                    margin: "4px 0 0",
                  }}
                >
                  Target by product, collection, tag, or product type.
                </p>
              </div>

              <div
                style={{
                  display: "flex",
                  gap: "10px",
                  alignItems: "flex-end",
                }}
              >
                {/* Type select */}
                <div style={{ flexShrink: 0 }}>
                  <label style={labelStyle} htmlFor="assignment-type">
                    Type
                  </label>
                  <select
                    id="assignment-type"
                    value={newAssignmentType}
                    onChange={(e) =>
                      setNewAssignmentType(
                        (e.target as HTMLSelectElement).value,
                      )
                    }
                    style={{
                      border: "1px solid #c9cccf",
                      borderRadius: "8px",
                      padding: "8px 10px",
                      fontSize: "13px",
                      background: "#fff",
                      cursor: "pointer",
                      outline: "none",
                      fontFamily: "inherit",
                      color: "#202223",
                    }}
                    onFocus={(e) => focusInput(e.target as HTMLSelectElement)}
                    onBlur={(e) => blurInput(e.target as HTMLSelectElement)}
                  >
                    {ASSIGNMENT_TYPES.map((t) => (
                      <option key={t.value} value={t.value}>
                        {t.label}
                      </option>
                    ))}
                  </select>
                </div>

                {/* Value input — hidden for "all" type */}
                {newAssignmentType !== "all" && (
                  <div style={{ flex: 1 }}>
                    <label style={labelStyle} htmlFor="assignment-value">
                      Value
                    </label>
                    <input
                      id="assignment-value"
                      value={newAssignmentValue}
                      onChange={(e) =>
                        setNewAssignmentValue(
                          (e.target as HTMLInputElement).value,
                        )
                      }
                      placeholder={
                        newAssignmentType === "tag"
                          ? "e.g. summer-sale"
                          : newAssignmentType === "product_type"
                            ? "e.g. T-Shirts"
                            : newAssignmentType === "collection"
                              ? "e.g. gid://shopify/Collection/123"
                              : "e.g. gid://shopify/Product/123"
                      }
                      style={inputStyle}
                      onFocus={(e) => focusInput(e.target as HTMLInputElement)}
                      onBlur={(e) => blurInput(e.target as HTMLInputElement)}
                      onKeyDown={(e) => {
                        if (e.key === "Enter") {
                          e.preventDefault();
                          handleAddAssignment();
                        }
                      }}
                    />
                  </div>
                )}

                <div style={{ flexShrink: 0, paddingBottom: "1px" }}>
                  <s-button
                    variant="primary"
                    onClick={handleAddAssignment}
                    loading={assignmentFetcher.state !== "idle"}
                  >
                    Add
                  </s-button>
                </div>
              </div>
            </div>
          )}
        </div>

        {/* ============================================================== */}
        {/* TAB: Settings                                                   */}
        {/* ============================================================== */}
        <div style={{ display: activeTab === "settings" ? "block" : "none" }}>
          {/* How to Measure card */}
          <div style={{ ...cardStyle, marginBottom: "16px" }}>
            <div style={{ marginBottom: "14px" }}>
              <p style={sectionTitle}>How to Measure</p>
              <p
                style={{
                  fontSize: "13px",
                  color: "#6d7175",
                  margin: "4px 0 0",
                }}
              >
                This guide is shown alongside your size chart to help customers
                measure correctly.
              </p>
            </div>
            <div
              style={{
                background: "#f9fafb",
                border: "1px solid #e1e3e5",
                borderRadius: "8px",
                padding: "16px 18px",
              }}
            >
              <p
                style={{
                  margin: "0 0 10px",
                  fontSize: "13px",
                  fontWeight: 700,
                  color: "#202223",
                }}
              >
                Measurement Instructions
              </p>
              <ul
                style={{
                  margin: 0,
                  padding: "0 0 0 18px",
                  listStyleType: "disc",
                }}
              >
                {[
                  {
                    label: "Chest",
                    desc: "Measure around the fullest part of your chest, keeping the tape parallel to the floor.",
                  },
                  {
                    label: "Waist",
                    desc: "Measure around the narrowest part of your waist, typically 1 inch above the navel.",
                  },
                  {
                    label: "Hips",
                    desc: "Measure around the fullest part of your hips, approximately 8 inches below the waist.",
                  },
                  {
                    label: "Inseam",
                    desc: "Measure from the crotch seam down to the ankle bone along the inside of the leg.",
                  },
                ].map((item) => (
                  <li
                    key={item.label}
                    style={{
                      fontSize: "13px",
                      color: "#202223",
                      lineHeight: 1.6,
                      marginBottom: "6px",
                    }}
                  >
                    <strong style={{ color: "#202223" }}>{item.label}:</strong>{" "}
                    <span style={{ color: "#6d7175" }}>{item.desc}</span>
                  </li>
                ))}
              </ul>
              <p
                style={{
                  margin: "12px 0 0",
                  fontSize: "12px",
                  color: "#8c9196",
                  fontStyle: "italic",
                }}
              >
                Tip: Use a soft measuring tape and measure directly on the skin
                or over light clothing for the most accurate fit.
              </p>
            </div>
          </div>

          {/* Danger Zone card */}
          {!isNew && (
            <div
              style={{
                background: "#fff8f8",
                border: "1px solid #fcd4d1",
                borderRadius: "12px",
                padding: "20px",
              }}
            >
              <p
                style={{
                  margin: "0 0 4px",
                  fontSize: "15px",
                  fontWeight: 650,
                  color: "#d82c0d",
                }}
              >
                Danger Zone
              </p>
              <p
                style={{
                  margin: "0 0 16px",
                  fontSize: "13px",
                  color: "#6d7175",
                  lineHeight: 1.5,
                }}
              >
                Permanently deletes this chart and all its product assignments.
                This action cannot be undone.
              </p>
              <assignmentFetcher.Form method="post">
                <input type="hidden" name="intent" value="delete" />
                <button
                  type="submit"
                  style={{
                    background: "#d82c0d",
                    border: "none",
                    borderRadius: "8px",
                    padding: "8px 16px",
                    fontSize: "13px",
                    fontWeight: 600,
                    color: "#fff",
                    cursor: "pointer",
                    fontFamily: "inherit",
                    transition: "background 0.1s",
                  }}
                  onMouseEnter={(e) => {
                    (e.currentTarget as HTMLButtonElement).style.background =
                      "#b52b0c";
                  }}
                  onMouseLeave={(e) => {
                    (e.currentTarget as HTMLButtonElement).style.background =
                      "#d82c0d";
                  }}
                >
                  Delete Chart Permanently
                </button>
              </assignmentFetcher.Form>
            </div>
          )}
        </div>
      </s-section>

      {/* ================================================================ */}
      {/* ASIDE — Live Widget Preview (always visible)                       */}
      {/* ================================================================ */}
      <s-section slot="aside" heading="Widget Preview">
        <ChartPreview data={chartData} name={name} status={status} />
        <p
          style={{
            fontSize: "12px",
            color: "#8c9196",
            marginTop: "10px",
            marginBottom: 0,
            textAlign: "center",
          }}
        >
          Live preview — reflects your edits instantly.
        </p>
      </s-section>

      {/* ================================================================ */}
      {/* ASIDE — Chart Info (always visible for saved charts)              */}
      {/* ================================================================ */}
      {!isNew && chart && (
        <s-section slot="aside" heading="Chart Info">
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              gap: "0",
            }}
          >
            {[
              { label: "Created", value: formatDate(chart.createdAt) },
              { label: "Last updated", value: formatDate(chart.updatedAt) },
              { label: "Assignments", value: String(assignments.length) },
              { label: "Sizes (rows)", value: String(chartData.rows.length) },
              { label: "Columns", value: String(chartData.headers.length) },
            ].map((item, idx, arr) => (
              <div
                key={item.label}
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "baseline",
                  padding: "8px 0",
                  borderBottom:
                    idx < arr.length - 1 ? "1px solid #f1f1f1" : "none",
                }}
              >
                <span
                  style={{
                    fontSize: "12px",
                    color: "#8c9196",
                    fontWeight: 500,
                  }}
                >
                  {item.label}
                </span>
                <span
                  style={{
                    fontSize: "13px",
                    color: "#202223",
                    fontWeight: 600,
                    textAlign: "right",
                    maxWidth: "55%",
                  }}
                >
                  {item.value}
                </span>
              </div>
            ))}
          </div>
        </s-section>
      )}
    </s-page>
  );
}

