            {assignments.length > 0 && (
              <div
                style={{
                  border: "1px solid #e3e3e3",
                  borderRadius: "8px",
                  overflow: "hidden",
                }}
              >
                {assignments.map((assignment, i) => (
                  <div
                    key={assignment.id}
                    style={{
                      display: "flex",
