<div style={{ display: activeTab === "recommendation" ? "block" : "none" }}>
  {/* Enable toggle card */}
  <div style={{ ...cardStyle, marginBottom: "16px" }}>
    <div
      style={{
        display: "flex",
        alignItems: "flex-start",
        justifyContent: "space-between",
        gap: "16px",
      }}
    >
      <div style={{ flex: 1 }}>
