      <div
        style={{
          marginTop: "16px",
          padding: "12px 14px",
          background: "#f0f5ff",
          border: "1px solid #c5d8f6",
          borderRadius: "8px",
          display: "flex",
          alignItems: "flex-start",
          gap: "10px",
        }}
      >
        <span style={{ fontSize: "16px", lineHeight: 1, marginTop: "1px" }}>&#10003;</span>
        <p style={{ margin: 0, fontSize: "13px", color: "#3b3f8c", fontWeight: 500 }}>
          Customers will see a "Find My Size" button on your product page. Make sure your chart has at least 3 size rows with chest and waist data for best accuracy.
        </p>
      </div>
    )}
  </div>

  {/* How it works card */}
  <div style={{ ...cardStyle, marginBottom: "16px" }}>
    <div style={{ marginBottom: "14px" }}>
      <p style={sectionTitle}>How AI Recommendations Work</p>
    </div>
    <div style={{ display: "flex", flexDirection: "column", gap: "14px" }}>
      {[
        { step: "1", title: "Customer enters measurements", desc: "Height, weight, and body type are collected via a short form shown next to your size chart." },
        { step: "2", title: "AI matches to your size data", desc: "Our algorithm cross-references the inputs with your chart rows to find the closest fit, weighted by body type." },
        { step: "3", title: "Personalized recommendation shown", desc: "The recommended size is highlighted in the chart with a confidence indicator (high/medium/low)." },
      ].map((item) => (
        <div key={item.step} style={{ display: "flex", gap: "14px", alignItems: "flex-start" }}>
          <div
            style={{
              width: "28px",
              height: "28px",
              borderRadius: "50%",
              background: "#2c6ecb",
              color: "#fff",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              fontSize: "13px",
              fontWeight: 700,
              flexShrink: 0,
            }}
          >
            {item.step}
          </div>
          <div>
            <p style={{ margin: "0 0 2px", fontSize: "14px", fontWeight: 600, color: "#202223" }}>{item.title}</p>
            <p style={{ margin: 0, fontSize: "13px", color: "#6d7175", lineHeight: 1.5 }}>{item.desc}</p>
          </div>
        </div>
      ))}
    </div>
  </div>

  {/* Requirements card */}
  <div
    style={{
      ...cardStyle,
      background: "#f9fafb",
      border: "1px solid #e3e3e3",
    }}
  >
    <p style={{ ...sectionTitle, marginBottom: "12px" }}>Requirements for Best Accuracy</p>
    <div style={{ display: "flex", flexDirection: "column", gap: "8px" }}>
      {[
        "At least 3 size rows (S, M, L or numeric sizes)",
        "Chest and/or waist measurements in your chart columns",
        "AI Recommender enabled in Recommender settings",
        "Starter plan or above",
      ].map((req) => (
        <div key={req} style={{ display: "flex", gap: "8px", alignItems: "flex-start" }}>
          <span style={{ color: "#2c6ecb", fontWeight: 700, fontSize: "14px", lineHeight: "20px", flexShrink: 0 }}>✓</span>
          <span style={{ fontSize: "13px", color: "#202223" }}>{req}</span>
        </div>
      ))}
    </div>
    <div style={{ marginTop: "16px" }}>
      <s-button href="/app/recommender">Configure Recommender Settings</s-button>
    </div>
  </div>
</div>

