                      }
                      style={{
                        width: "100%",
                        border: "none",
                        background: "transparent",
                        padding: "9px 10px",
                        fontSize: "13px",
                        color: "#202223",
                        outline: "none",
                        boxSizing: "border-box",
                        fontFamily: "inherit",
                      }}
                      onFocus={(e) => {
                        (
                          e.target as HTMLInputElement
                        ).parentElement!.style.boxShadow =
                          "inset 0 0 0 2px #2c6ecb";
                        (
                          e.target as HTMLInputElement
                        ).parentElement!.style.background = "#f0f5ff";
                      }}
                      onBlur={(e) => {
                        (
                          e.target as HTMLInputElement
                        ).parentElement!.style.boxShadow = "none";
                        (
                          e.target as HTMLInputElement
                        ).parentElement!.style.background = "transparent";
                      }}
                      placeholder="—"
                    />
                  </td>
                ))}

                {/* Column spacer — aligns under add column button */}
                <td
                  style={{
                    borderBottom:
                      ri < data.rows.length - 1 ? "1px solid #e1e3e5" : "none",
                    borderRight: "1px solid #e1e3e5",
                    width: "40px",
                    background: "transparent",
                  }}
                />

                {/* Remove row button */}
                <td
                  style={{
                    borderBottom:
                      ri < data.rows.length - 1 ? "1px solid #e1e3e5" : "none",
                    padding: "0",
                    textAlign: "center",
                    width: "36px",
                    background: "transparent",
                  }}
                >
                  <button
                    type="button"
                    onClick={() => removeRow(ri)}
                    title="Remove row"
                    style={{
                      background: "none",
                      border: "none",
                      cursor: "pointer",
                      color: "#c9cccf",
                      fontSize: "16px",
                      lineHeight: 1,
                      padding: "4px 8px",
                      borderRadius: "4px",
                      transition: "color 0.1s, background 0.1s",
                      fontFamily: "inherit",
                    }}
                    onMouseEnter={(e) => {
                      (e.currentTarget as HTMLButtonElement).style.color =
                        "#d82c0d";
                      (e.currentTarget as HTMLButtonElement).style.background =
                        "#fee2e2";
                    }}
                    onMouseLeave={(e) => {
                      (e.currentTarget as HTMLButtonElement).style.color =
                        "#c9cccf";
                      (e.currentTarget as HTMLButtonElement).style.background =
                        "none";
                    }}
                  >
                    &times;
                  </button>
                </td>
              </tr>
            ))}

            {/* Add row footer */}
            <tr>
              <td
                colSpan={data.headers.length + 2}
                style={{
                  padding: "0",
                  background: "#f6f6f7",
                  borderTop: "1px solid #e1e3e5",
                }}
              >
                <button
                  type="button"
                  onClick={addRow}
                  style={{
                    display: "block",
                    width: "100%",
                    background: "none",
                    border: "none",
                    cursor: "pointer",
                    color: "#2c6ecb",
                    fontSize: "13px",
                    fontWeight: 600,
                    padding: "10px 14px",
                    textAlign: "left",
                    transition: "background 0.1s",
                    fontFamily: "inherit",
                  }}
                  onMouseEnter={(e) => {
                    (e.currentTarget as HTMLButtonElement).style.background =
                      "#e8f0fe";
                  }}
                  onMouseLeave={(e) => {
                    (e.currentTarget as HTMLButtonElement).style.background =
                      "none";
                  }}
                >
                  + Add row
                </button>
              </td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  );
}

