              <span style={{ fontSize: "12px", color: "#6d7175" }}>
                ${plan.price}/mo
              </span>
            )}
          </div>

          {maxCharts === -1 ? (
            <p style={{ fontSize: "13px", color: "#6d7175", margin: "0 0 14px" }}>
              Unlimited charts on your plan.
            </p>
          ) : (
            <>
              <div
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                  marginBottom: "6px",
                }}
              >
                <p
                  style={{
                    fontSize: "13px",
                    color: "#202223",
                    margin: 0,
                    fontWeight: 600,
                  }}
                >
                  {publishedCount} / {maxCharts} published
                </p>
                <span style={{ fontSize: "12px", color: "#8c9196" }}>
                  {draftCount} draft
                </span>
              </div>
              <div
                style={{
                  height: "6px",
                  background: "#e4e5e7",
                  borderRadius: "3px",
                  overflow: "hidden",
                  marginBottom: "6px",
                }}
              >
                <div
                  style={{
                    height: "100%",
                    width: `${progressPct}%`,
                    background: progressColor,
                    borderRadius: "3px",
                    transition: "width 0.3s ease",
                  }}
                />
              </div>
              <p style={{ fontSize: "12px", color: "#8c9196", margin: "0 0 16px" }}>
                {maxCharts - publishedCount > 0
                  ? `${maxCharts - publishedCount} slot${maxCharts - publishedCount !== 1 ? "s" : ""} remaining`
                  : "Limit reached — upgrade for more"}
              </p>
              <s-button href="/app/pricing" variant="primary">
                Upgrade for unlimited
              </s-button>
            </>
          )}
        </div>
      </s-section>

      {/* ================================================================ */}
      {/* ASIDE — Quick Tips                                                */}
      {/* ================================================================ */}
      <s-section slot="aside" heading="Quick tips">
        <s-unordered-list>
          <s-list-item>
            Assign charts to products or collections for automatic display in your
            storefront widget
          </s-list-item>
          <s-list-item>
            Templates include standard sizing data so you can get started fast
          </s-list-item>
          <s-list-item>
            Publish a chart to make it visible to customers on your store
          </s-list-item>
          <s-list-item>
            Add both inch and centimeter values for international shoppers
          </s-list-item>
        </s-unordered-list>
      </s-section>
    </s-page>
  );
}

