  padding: "20px",
};

const sectionTitle: React.CSSProperties = {
  fontSize: "15px",
  fontWeight: 650,
  color: "#202223",
  margin: 0,
};

const badgeStyle = (tone: "success" | "neutral" | "info"): React.CSSProperties => ({
  display: "inline-block",
  padding: "2px 8px",
  borderRadius: "10px",
