export default function SizeCharts() {
  const { charts, plan, templates, categories, canCreate } =
    useLoaderData<typeof loader>();
  const fetcher = useFetcher<typeof action>();
  const shopify = useAppBridge();

  const [showTemplates, setShowTemplates] = useState(false);
  const [showImport, setShowImport] = useState(false);
  const [importName, setImportName] = useState("Imported Size Chart");
  const [importCategory, setImportCategory] = useState("general");
  const [importCsvText, setImportCsvText] = useState("");
  const [statusFilter, setStatusFilter] = useState<"all" | "active" | "draft">("all");
  const [categoryFilter, setCategoryFilter] = useState("all");
  const [searchQuery, setSearchQuery] = useState("");

  const isLoading = fetcher.state !== "idle";

  useEffect(() => {
    if (!fetcher.data) return;
    const data = fetcher.data as ActionData;
    if ("ok" in data && data.ok) {
      shopify.toast.show(data.message);
      if ("redirectId" in data && data.redirectId) {
        window.location.href = `/app/size-charts/${data.redirectId}`;
      } else {
        setShowTemplates(false);
        setShowImport(false);
        setImportCsvText("");
        setImportName("Imported Size Chart");
      }
    } else if ("error" in data) {
      shopify.toast.show(data.error, { isError: true });
    }
  }, [fetcher.data, shopify]);

  const filteredCharts = charts.filter((chart) => {
    const matchesStatus = statusFilter === "all" || chart.status === statusFilter;
    const matchesCategory = categoryFilter === "all" || chart.category === categoryFilter;
    const matchesSearch =
      searchQuery.trim() === "" ||
      chart.name.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesStatus && matchesCategory && matchesSearch;
  });

  const publishedCount = charts.filter((c) => c.status === "active").length;
  const draftCount = charts.filter((c) => c.status === "draft").length;
  const activeFilteredCount = charts.filter((c) => c.status === "active").length;
  const draftFilteredCount = charts.filter((c) => c.status === "draft").length;
  const maxCharts = plan.limits.maxCharts;
  const isFreePlan = plan.id === "free";

  const progressPct =
    maxCharts > 0 ? Math.min(100, Math.round((publishedCount / maxCharts) * 100)) : 0;
  const progressColor =
    publishedCount >= maxCharts && maxCharts > 0 ? "#d72c0d" : "#1a73e8";

  function clearFilters() {
    setStatusFilter("all");
    setCategoryFilter("all");
    setSearchQuery("");
  }

  return (
    <s-page heading="Size Charts">
      {/* Primary action */}
      <s-button
        slot="primary-action"
        variant="primary"
        onClick={() => setShowTemplates(!showTemplates)}
        disabled={!canCreate || isLoading}
      >
        {canCreate
          ? showTemplates
            ? "Cancel"
            : "Create chart"
          : `Limit reached (${plan.limits.maxCharts})`}
      </s-button>

      <s-button
        slot="secondary-action"
        onClick={() => { setShowImport(!showImport); setShowTemplates(false); }}
      >
        Import CSV
      </s-button>

      {/* Subtitle */}
      <s-text tone="neutral">
        Manage your size charts and assign them to products
      </s-text>

      {/* ================================================================ */}
      {/* PLAN LIMIT BANNER                                                 */}
      {/* ================================================================ */}
      {!canCreate && (
        <s-section>
          <div
            style={{
              ...cardStyle,
              background: "#fff8ec",
              border: "1px solid #ffd79d",
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
              gap: "16px",
            }}
          >
            <div style={{ display: "flex", alignItems: "flex-start", gap: "12px" }}>
              <span style={{ fontSize: "20px", flexShrink: 0, marginTop: "1px" }}>
                ⚠️
              </span>
              <div>
                <p
                  style={{
                    margin: "0 0 4px",
                    fontSize: "14px",
                    fontWeight: 600,
                    color: "#202223",
                  }}
                >
                  Chart limit reached
                </p>
                <p style={{ margin: 0, fontSize: "13px", color: "#6d7175" }}>
                  You have reached the {plan.limits.maxCharts}-chart limit on the{" "}
                  {plan.name} plan. Upgrade to Starter for unlimited charts with no
                  hidden fees.
                </p>
              </div>
            </div>
            <s-button href="/app/pricing" variant="primary">
              Upgrade plan
            </s-button>
          </div>
        </s-section>
      )}

      {/* ================================================================ */}
      {/* TEMPLATE PICKER                                                   */}
      {/* ================================================================ */}
      {showTemplates && (
        <TemplatePicker
          templates={templates}
          categories={categories}
          isLoading={isLoading}
          onClose={() => setShowTemplates(false)}
          fetcher={fetcher}
        />
      )}

      {/* ================================================================ */}
      {/* SEARCH + FILTER BAR (only when charts exist)                     */}
      {/* ================================================================ */}
      {charts.length > 0 && (
        <s-section>
          <div style={cardStyle}>
            {/* Search input */}
            <div style={{ marginBottom: "12px" }}>
              <div
                style={{
                  position: "relative",
                  display: "flex",
                  alignItems: "center",
                }}
              >
                <span
                  style={{
                    position: "absolute",
                    left: "12px",
                    fontSize: "14px",
                    color: "#8c9196",
                    pointerEvents: "none",
                  }}
                >
                  🔍
                </span>
                <input
                  type="text"
                  placeholder="Search charts..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery((e.target as HTMLInputElement).value)}
                  style={{
                    width: "100%",
                    border: "1px solid #c9cccf",
                    borderRadius: "8px",
                    padding: "8px 12px 8px 36px",
                    fontSize: "14px",
                    color: "#202223",
                    background: "#fff",
                    outline: "none",
                    boxSizing: "border-box",
                  }}
                />
              </div>
            </div>

            {/* Status pill tabs + Category dropdown */}
            <div
              style={{
                display: "flex",
                alignItems: "center",
                justifyContent: "space-between",
                gap: "12px",
                flexWrap: "wrap",
              }}
            >
              {/* Status pill tabs */}
              <div style={{ display: "flex", alignItems: "center", gap: "6px" }}>
                {(
                  [
                    { key: "all", label: `All (${charts.length})` },
                    { key: "active", label: `Active (${activeFilteredCount})` },
                    { key: "draft", label: `Draft (${draftFilteredCount})` },
                  ] as const
                ).map((tab) => (
                  <button
                    key={tab.key}
                    onClick={() => setStatusFilter(tab.key)}
                    style={{
                      border: "1px solid",
                      borderColor: statusFilter === tab.key ? "#1a73e8" : "#c9cccf",
                      borderRadius: "20px",
                      padding: "4px 14px",
                      fontSize: "13px",
                      fontWeight: statusFilter === tab.key ? 600 : 400,
                      background: statusFilter === tab.key ? "#1a73e8" : "#fff",
                      color: statusFilter === tab.key ? "#fff" : "#6d7175",
                      cursor: "pointer",
                      transition: "all 0.15s ease",
                      lineHeight: "22px",
                    }}
                  >
                    {tab.label}
                  </button>
                ))}
              </div>

              {/* Category select */}
              <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
                <span style={{ fontSize: "13px", color: "#6d7175", whiteSpace: "nowrap" }}>
                  Category:
                </span>
                <select
                  value={categoryFilter}
                  onChange={(e) =>
                    setCategoryFilter((e.target as HTMLSelectElement).value)
                  }
                  style={{
                    border: "1px solid #c9cccf",
                    borderRadius: "8px",
                    padding: "5px 10px",
                    fontSize: "13px",
                    background: "#fff",
                    color: "#202223",
                    cursor: "pointer",
                    outline: "none",
                  }}
                >
                  <option value="all">All</option>
                  {categories.map((cat) => (
                    <option key={cat} value={cat}>
                      {CATEGORY_LABELS[cat] ?? cat}
                    </option>
                  ))}
                </select>
              </div>
            </div>
          </div>
        </s-section>
      )}

      {/* ================================================================ */}
      {/* CHARTS LIST                                                       */}
      {/* ================================================================ */}
      <s-section>
        <div style={cardStyle}>
          {/* Section header */}
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              marginBottom: charts.length > 0 ? "4px" : "0",
            }}
          >
            {charts.length > 0 && (
              <p style={sectionTitle}>
                Size Charts{" "}
                <span style={{ fontWeight: 400, color: "#6d7175" }}>
                  ({filteredCharts.length}
                  {filteredCharts.length !== charts.length ? ` of ${charts.length}` : ""})
                </span>
              </p>
            )}
          </div>

          {/* Empty state — no charts at all */}
          {charts.length === 0 && (
            <div style={{ textAlign: "center", padding: "56px 24px" }}>
              <div
                style={{
                  width: "64px",
                  height: "64px",
                  borderRadius: "50%",
                  background: "#e8f0fe",
                  margin: "0 auto 20px",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  fontSize: "28px",
                }}
              >
                📐
              </div>
              <p
                style={{
                  fontSize: "16px",
                  fontWeight: 650,
                  color: "#202223",
                  margin: "0 0 8px",
                }}
              >
                Create your first size chart
              </p>
              <p
                style={{
                  fontSize: "13px",
                  color: "#6d7175",
                  margin: "0 auto 24px",
                  maxWidth: "380px",
                  lineHeight: "1.6",
                }}
              >
                Start by creating a size chart to help your customers find the right
                size. Reduce size-related returns by up to 40% — get started in under
                3 minutes using one of our pre-built templates.
              </p>
              <s-button variant="primary" onClick={() => setShowTemplates(true)}>
                Create chart
              </s-button>
            </div>
          )}

          {/* Empty state — filters applied but no results */}
          {charts.length > 0 && filteredCharts.length === 0 && (
            <div style={{ textAlign: "center", padding: "48px 24px" }}>
              <div
                style={{
                  width: "48px",
                  height: "48px",
                  borderRadius: "50%",
                  background: "#f4f6f8",
                  margin: "0 auto 16px",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  fontSize: "22px",
                }}
              >
                🔍
              </div>
              <p
                style={{
                  fontSize: "15px",
                  fontWeight: 600,
                  color: "#202223",
                  margin: "0 0 6px",
                }}
              >
                No charts match your filters
              </p>
              <p
                style={{
                  fontSize: "13px",
                  color: "#6d7175",
                  margin: "0 0 20px",
                }}
              >
                Try adjusting your search or filters to find what you are looking for.
              </p>
              <s-button onClick={clearFilters}>Clear filters</s-button>
            </div>
          )}

          {/* Chart rows */}
          {filteredCharts.length > 0 && (
            <div style={{ marginTop: "8px" }}>
              {filteredCharts.map((chart, i) => (
                <div
                  key={chart.id}
                  style={{
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "space-between",
                    padding: "14px 0",
                    borderBottom:
                      i === filteredCharts.length - 1
                        ? "none"
                        : "1px solid #f1f1f1",
                    gap: "16px",
                  }}
                >
                  {/* Left: name + meta */}
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ marginBottom: "6px" }}>
                      <s-link href={`/app/size-charts/${chart.id}`}>
                        <span
                          style={{
                            fontWeight: 600,
                            fontSize: "14px",
                            color: "#202223",
                          }}
                        >
                          {chart.name}
                        </span>
                      </s-link>
                    </div>
                    <div
                      style={{
                        display: "flex",
                        alignItems: "center",
                        gap: "6px",
                        flexWrap: "wrap",
                      }}
                    >
                      <span
                        style={badgeStyle(
                          chart.status === "active" ? "success" : "neutral",
                        )}
                      >
                        {chart.status === "active" ? "Active" : "Draft"}
                      </span>
                      <span style={badgeStyle("info")}>
                        {CATEGORY_LABELS[chart.category] ?? chart.category}
                      </span>
                      <span style={{ fontSize: "12px", color: "#c9cccf" }}>·</span>
                      <span style={{ fontSize: "12px", color: "#8c9196" }}>
                        {chart.assignments.length > 0
                          ? `${chart.assignments.length} product${chart.assignments.length !== 1 ? "s" : ""} assigned`
                          : "No assignments"}
                      </span>
                      <span style={{ fontSize: "12px", color: "#c9cccf" }}>·</span>
                      <span style={{ fontSize: "12px", color: "#8c9196" }}>
                        Updated {formatDate(chart.updatedAt)}
                      </span>
                    </div>
                  </div>

                  {/* Right: actions */}
                  <div
                    style={{
                      display: "flex",
                      alignItems: "center",
                      gap: "6px",
                      flexShrink: 0,
                    }}
                  >
                    <s-button href={`/app/size-charts/${chart.id}`} variant="tertiary">
                      Edit
                    </s-button>

                    <fetcher.Form method="post">
                      <input type="hidden" name="intent" value="toggle-status" />
                      <input type="hidden" name="id" value={chart.id} />
                      <s-button type="submit" loading={isLoading}>
                        {chart.status === "active" ? "Unpublish" : "Publish"}
                      </s-button>
                    </fetcher.Form>

                    <fetcher.Form method="post">
                      <input type="hidden" name="intent" value="duplicate" />
                      <input type="hidden" name="id" value={chart.id} />
                      <s-button type="submit" loading={isLoading}>
                        Duplicate
                      </s-button>
                    </fetcher.Form>

                    <fetcher.Form method="post">
                      <input type="hidden" name="intent" value="delete" />
                      <input type="hidden" name="id" value={chart.id} />
                      <s-button
                        type="submit"
                        variant="tertiary"
                        tone="critical"
                        loading={isLoading}
                      >
                        Delete
                      </s-button>
                    </fetcher.Form>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </s-section>

      {/* ================================================================ */}
      {/* ASIDE — Chart Limits                                              */}
      {/* ================================================================ */}
      <s-section slot="aside" heading="Chart limits">
        <div style={{ ...cardStyle, padding: "16px" }}>
          {/* Plan badge row */}
          <div
            style={{
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
              marginBottom: "14px",
            }}
          >
            <span
              style={{
                ...badgeStyle(isFreePlan ? "neutral" : "success"),
                fontSize: "12px",
              }}
            >
              {plan.name} Plan
            </span>
            {plan.price > 0 && (
              <span style={{ fontSize: "12px", color: "#6d7175" }}>
                ${plan.price}/mo
              </span>
            )}
          </div>

          {maxCharts === -1 ? (
            <p style={{ fontSize: "13px", color: "#6d7175", margin: "0 0 14px" }}>
              Unlimited charts on your plan.
            </p>
          ) : (
            <>
              <div
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                  marginBottom: "6px",
                }}
              >
                <p
                  style={{
                    fontSize: "13px",
                    color: "#202223",
                    margin: 0,
                    fontWeight: 600,
                  }}
                >
                  {publishedCount} / {maxCharts} published
                </p>
                <span style={{ fontSize: "12px", color: "#8c9196" }}>
                  {draftCount} draft
                </span>
              </div>
              <div
                style={{
                  height: "6px",
                  background: "#e4e5e7",
                  borderRadius: "3px",
                  overflow: "hidden",
                  marginBottom: "6px",
                }}
              >
                <div
                  style={{
                    height: "100%",
                    width: `${progressPct}%`,
                    background: progressColor,
                    borderRadius: "3px",
                    transition: "width 0.3s ease",
                  }}
                />
              </div>
              <p style={{ fontSize: "12px", color: "#8c9196", margin: "0 0 16px" }}>
                {maxCharts - publishedCount > 0
                  ? `${maxCharts - publishedCount} slot${maxCharts - publishedCount !== 1 ? "s" : ""} remaining`
                  : "Limit reached — upgrade for more"}
              </p>
              <s-button href="/app/pricing" variant="primary">
                Upgrade for unlimited
              </s-button>
            </>
          )}
        </div>
      </s-section>

      {/* ================================================================ */}
      {/* ASIDE — Quick Tips                                                */}
      {/* ================================================================ */}
      <s-section slot="aside" heading="Quick tips">
        <s-unordered-list>
          <s-list-item>
            Assign charts to products or collections for automatic display in your
            storefront widget
          </s-list-item>
          <s-list-item>
            Templates include standard sizing data so you can get started fast
          </s-list-item>
          <s-list-item>
            Publish a chart to make it visible to customers on your store
          </s-list-item>
          <s-list-item>
            Add both inch and centimeter values for international shoppers
          </s-list-item>
        </s-unordered-list>
      </s-section>
    </s-page>
  );
}

