import type { HeadersFunction, LoaderFunctionArgs } from "react-router";
import { Outlet, useLoaderData, useRouteError } from "react-router";
import { boundary } from "@shopify/shopify-app-react-router/server";
import { AppProvider } from "@shopify/shopify-app-react-router/react";

import { authenticate } from "../shopify.server";

export const loader = async ({ request }: LoaderFunctionArgs) => {
  await authenticate.admin(request);

  // eslint-disable-next-line no-undef
  return { apiKey: process.env.SHOPIFY_API_KEY || "" };
};

export default function App() {
  const { apiKey } = useLoaderData<typeof loader>();

  return (
    <AppProvider embedded apiKey={apiKey}>
      <s-app-nav>
        <s-link href="/app">Dashboard</s-link>
        <s-link href="/app/size-charts">Size Charts</s-link>
        <s-link href="/app/recommender">AI Recommender</s-link>
        <s-link href="/app/widget">Widget</s-link>
        <s-link href="/app/analytics">Analytics</s-link>
        <s-link href="/app/pricing">Pricing</s-link>
        <s-link href="/app/settings">Settings</s-link>
      </s-app-nav>
      <Outlet />
    </AppProvider>
  );
}

// Shopify needs React Router to catch some thrown responses, so that their headers are included in the response.
export function ErrorBoundary() {
  return boundary.error(useRouteError());
}

export const headers: HeadersFunction = (headersArgs) => {
  return boundary.headers(headersArgs);
};

import type { LoaderFunctionArgs } from "react-router";
import { useLoaderData } from "react-router";
import { authenticate } from "../shopify.server";
import db from "../db.server";
import { PLANS, getPlan } from "../lib/plans";

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const subscription = await db.subscription.findUnique({ where: { shop: session.shop } });
  return { currentPlan: getPlan(subscription?.planId ?? "free"), plans: PLANS };
};

export default function Pricing() {
  const { currentPlan, plans } = useLoaderData<typeof loader>();

  return (
    <s-page heading="Plans & Pricing">
      <s-section>
        <s-stack direction="block" gap="base">
          <s-heading>Simple, transparent pricing. No per-order fees. No hidden charges. Ever.</s-heading>
          <s-text tone="neutral">
            Current plan: {currentPlan.name}{currentPlan.price > 0 ? ` ($${currentPlan.price}/mo)` : " (Free)"}
          </s-text>
        </s-stack>
      </s-section>

      <s-section>
        <s-stack direction="inline" gap="base">
          {plans.map((plan) => {
            const isCurrent = plan.id === currentPlan.id;
            const isUpgrade = plans.indexOf(plan) > plans.indexOf(currentPlan);

            return (
              <s-box key={plan.id} padding="base" borderWidth="base" borderRadius="base" background={isCurrent ? "subdued" : undefined}>
                <s-stack direction="block" gap="base">
                  <s-stack direction="block" gap="small-200">
                    <s-heading>{plan.name}</s-heading>
                    <s-text>
                      {plan.price === 0 ? "Free" : `$${plan.price}/month`}
                    </s-text>
                    {plan.price > 0 && (
                      <s-text tone="neutral">or ${plan.annualPrice}/year (save 20%)</s-text>
                    )}
                  </s-stack>

                  <s-unordered-list>
                    {plan.features.map((feature, i) => (
                      <s-list-item key={i}>{feature}</s-list-item>
                    ))}
                  </s-unordered-list>

                  {isCurrent ? (
                    <s-button disabled>Current Plan</s-button>
                  ) : isUpgrade ? (
                    <s-button variant="primary">Upgrade to {plan.name}</s-button>
                  ) : (
                    <s-button variant="tertiary">Downgrade to {plan.name}</s-button>
                  )}
                </s-stack>
              </s-box>
            );
          })}
        </s-stack>
      </s-section>

      <s-section heading="Why Merchants Switch to Us">
        <s-stack direction="inline" gap="base">
          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-text>No Per-Order Fees</s-text>
            <s-text tone="neutral">
              Unlike competitors who charge per order, we use simple flat pricing. No surprises.
            </s-text>
          </s-box>
          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-text>No Watermark on Free</s-text>
            <s-text tone="neutral">
              Even our free plan has no watermark. Your store stays clean and professional.
            </s-text>
          </s-box>
          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-text>20% Annual Discount</s-text>
            <s-text tone="neutral">
              Pay annually and save 2 months. Cancel anytime.
            </s-text>
          </s-box>
        </s-stack>
      </s-section>

      <s-section slot="aside" heading="FAQ">
        <s-stack direction="block" gap="base">
          <s-stack direction="block" gap="small-200">
            <s-text>Can I switch plans anytime?</s-text>
            <s-text tone="neutral">Yes. Upgrade instantly, downgrade at end of billing period.</s-text>
          </s-stack>
          <s-stack direction="block" gap="small-200">
            <s-text>What happens to my charts if I downgrade?</s-text>
            <s-text tone="neutral">Charts are never deleted. On Free, only the 3 most recent stay published.</s-text>
          </s-stack>
          <s-stack direction="block" gap="small-200">
            <s-text>Is there a free trial?</s-text>

