                              </s-text>
                              <s-button
                                variant="primary"
                                href={step.actionUrl}
                              >
                                {step.actionLabel}
                              </s-button>
                            </s-stack>
                          )}
                        </s-stack>
                      </s-stack>
                    </s-box>
                  ))}
                </s-stack>
              )}
            </s-stack>
          </s-box>
        </s-section>
