<s-box padding="base" borderWidth="base" borderRadius="base" style={{ marginBottom: "16px", display: "block" }}>
  <s-stack direction="block" gap="base">
    <div>
      <s-heading>Display Priority</s-heading>
      <s-text color="subdued">When multiple charts match a product, the one with the lowest priority number is shown first.</s-text>
    </div>
    <s-stack direction="inline" gap="base">
      <s-number-field
        label="Priority level"
        value={priority}
        min={1}
        max={100}
        onChange={(e: Event) => setPriority(Math.max(1, Math.min(100, parseInt((e.target as HTMLInputElement).value, 10) || 1)))}
      />
      <div style={{ alignSelf: "flex-end", paddingBottom: "8px" }}>
        <s-text color="subdued">
          {priority === 1 ? "Highest priority" : priority <= 5 ? "High priority" : priority <= 20 ? "Medium priority" : "Low priority"}
        </s-text>
      </div>
    </s-stack>
  </s-stack>
</s-box>

{/* Display Position card */}
<s-box padding="base" borderWidth="base" borderRadius="base" style={{ marginBottom: "16px", display: "block" }}>
  <s-stack direction="block" gap="base">
    <div>
      <s-heading>Widget Button Position</s-heading>
      <s-text color="subdued">Choose where the "Size Guide" button appears on your product pages.</s-text>
    </div>
    <s-stack direction="block" gap="base">
      {(
        [
          { value: "floating" as const, label: "Floating button", desc: "A floating button appears near the size selector — highest visibility" },
          { value: "above_desc" as const, label: "Above description", desc: "Shown above the product description section" },
          { value: "below_desc" as const, label: "Below description", desc: "Shown below the product description section" },
        ] satisfies { value: "floating" | "above_desc" | "below_desc"; label: string; desc: string }[]
      ).map((opt) => (
        <s-box
          key={opt.value}
          padding="base"
          border-width="base"
          border-radius="base"
          style={{
            cursor: "pointer",
            borderColor: buttonPosition === opt.value ? "#2c6ecb" : "#e3e3e3",
            background: buttonPosition === opt.value ? "#f0f5ff" : "#fff",
            display: "block",
          }}
          onClick={() => setButtonPosition(opt.value)}
        >
          <s-stack direction="inline" gap="base">
            <input
              type="radio"
              name="buttonPosition"
              value={opt.value}
              checked={buttonPosition === opt.value}
              onChange={() => setButtonPosition(opt.value)}
              style={{ marginTop: "2px", accentColor: "#2c6ecb", flexShrink: 0 }}
            />
            <s-stack direction="block" gap="small-200">
              <s-text>{opt.label}</s-text>
              <s-text color="subdued">{opt.desc}</s-text>
            </s-stack>
          </s-stack>
        </s-box>
      ))}
    </s-stack>
  </s-stack>
</s-box>

{/* Country Targeting card */}
<s-box padding="base" borderWidth="base" borderRadius="base" style={{ display: "block" }}>
  <s-stack direction="block" gap="base">
    <div>
      <s-heading>Country Targeting</s-heading>
      <s-text color="subdued">Limit this chart to customers in specific countries (e.g. show EU sizing only in Europe).</s-text>
    </div>
    <s-stack direction="block" gap="base">
      {(
        [
          { value: "all" as const, label: "All countries", desc: "Show this chart to all visitors regardless of location" },
          { value: "selected" as const, label: "Specific countries", desc: "Restrict to selected country codes (e.g. US, GB, DE)" },
        ] satisfies { value: "all" | "selected"; label: string; desc: string }[]
