            borderColor: countries === opt.value ? "#2c6ecb" : "#e3e3e3",
            background: countries === opt.value ? "#f0f5ff" : "#fff",
            display: "block",
          }}
          onClick={() => setCountries(opt.value)}
        >
          <s-stack direction="inline" gap="base">
            <input
              type="radio"
              name="countries"
              value={opt.value}
              checked={countries === opt.value}
              onChange={() => setCountries(opt.value)}
              style={{ marginTop: "2px", accentColor: "#2c6ecb", flexShrink: 0 }}
            />
            <s-stack direction="block" gap="small-200">
              <s-text>{opt.label}</s-text>
              <s-text color="subdued">{opt.desc}</s-text>
            </s-stack>
          </s-stack>
        </s-box>
      ))}
    </s-stack>
