function StepCircle({ done }: { done: boolean }) {
  return (
    <div
      style={{
        width: "22px",
        height: "22px",
        borderRadius: "50%",
        border: done ? "none" : "2px solid #c9cccf",
        background: done ? "#1a73e8" : "transparent",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        flexShrink: 0,
        marginTop: "1px",
        color: "#fff",
        fontSize: "12px",
        fontWeight: 700,
      }}
    >
      {done && "✓"}
    </div>
  );
}

